// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(0, "", ""); }
    function testFuzz_property(uint256 burnAmount) public {
        vm.assume(burnAmount > 0 && burnAmount <= type(uint256).max / 2);

        c.mintToken(address(this), burnAmount);

        uint256 totalSupplyBefore = c.totalSupply();
        c.burn(burnAmount);
        uint256 totalSupplyAfter = c.totalSupply();

        assertTrue(totalSupplyAfter < totalSupplyBefore);
    }
}
